#!/usr/bin/env node
// L2-sample picker for the article-level3 (L2→L3) skill — the read half of the
// GAS handleL3Batch sampling logic, as a deterministic CCR script. The LLM owns
// the synthesis (the analysis prose); this script owns "which 3 L2 explanations
// do we synthesise next", so the selection can't drift from the GAS rule.
//
// Unlike article-level2's coverage-based picker (every uncovered L1 gets exactly
// one explanation), L3 is *sampling-based*: it draws a small rolling sample of
// recent L2 explanations and looks for the deeper principle connecting them.
// GAS keeps that sampling honest with two pieces of mutable Script-Property
// state — L3_LAST_RUN_AT and L3_RECENTLY_USED_L2_IDS. A Cadence fire is
// stateless, so this picker RECONSTRUCTS both from Notion (no extra store):
//
//   • "last run"      → the created_time of the most recent analysis (L3) row.
//                       L2s created after it are the "fresh" pool (the
//                       fresh-entry gate: at least one new L2 since the last L3).
//   • "recently used" → the SourceURLs recorded on the most recent L3 rows.
//                       publish-notion.mjs stamps each L3 with its source L2
//                       URLs, so the reuse-avoidance set is derivable from the
//                       corpus itself. Reuse is keyed on the L2's own SourceURL
//                       (a stable per-L2 identity — it's the L1 it covered).
//
// Same gating as handleL3Batch: 14-day recent window, sample size 3, skip when
// no fresh L2 has arrived or fewer than 3 L2s exist in the window.
//
// The CCR session never reads Secrets Manager: NOTION_API_KEY arrives inline
// from the task's `credentials["notion.integration_token"].apiKey` and is passed
// through as an env var by the runner. The unified DB id is NOT secret (already
// committed in newsletter/pipeline/normalize-categories.mjs), so it's a constant below —
// overridable by env for tests / migrations.
//
// Usage:
//   NOTION_API_KEY="<credentials['notion.integration_token'].apiKey>" \
//     node workforce/skills/article-level3/pick-l2-sources.mjs
//
// Stdout (single JSON line):
//   { "sources": [ { l2PageId, title, abstract, sourceUrl, category }, x3 ],
//     "canonicalCategory": "B: Role Blurring",   ← majority A–E bucket of the 3
//     "sourceUrls": "https://… , https://…" }    ← comma-joined, for --source-urls
//   { "skip": true, "reason": "..." }            ← nothing to do this fire
//
// Exit codes:
//   0  — printed a pick OR a {skip:true} (both are valid outcomes)
//   1  — bad env
//   3  — Notion API / network error

const NOTION_VERSION = "2022-06-28";
const NOTION_API = "https://api.notion.com/v1";

// Non-secret unified Articles DB id (mirror of the default in
// newsletter/pipeline/normalize-categories.mjs and article-level2's scripts). Env override
// allows test/migration.
const UNIFIED_DB_ID = process.env.UNIFIED_DB_ID || process.env.NOTION_DB_ID || "34fd0f0b-e61e-817a-9f6b-dc65b0d5b4cc";

// Sampling parameters — mirror of newsletter/gas/src/Code.gs L3_* constants.
const L3_RECENT_DAYS = Number(process.env.L3_RECENT_DAYS || 14);
const L3_SAMPLE_SIZE = Number(process.env.L3_SAMPLE_SIZE || 3);
const L3_AVOID_REUSE_COUNT = Number(process.env.L3_AVOID_REUSE_COUNT || 10);

// Canonical A–E buckets — mirror of newsletter/gas/src/Code.gs CATEGORY_NAMES +
// canonicalCategoryFor + pickCanonicalFromSources, so the L3 row groups under
// the same controlled bucket the GAS synthesis would have chosen (majority vote
// across the source L2s' categories).
const CATEGORY_NAMES = {
  A: "A: AI Hyper-productivity",
  B: "B: Role Blurring",
  C: "C: New Roles/FDE",
  D: "D: Big Tech Layoffs & AI Pivot",
  E: "E: Rethinking SDLC",
};
function canonicalCategoryFor(text) {
  const trimmed = (text || "").trim();
  if (!trimmed) return "";
  if (/^[A-E]$/i.test(trimmed)) return CATEGORY_NAMES[trimmed.toUpperCase()] || "";
  const m = trimmed.match(/^([A-E])[\s:：][\s\S]*$/i);
  if (m) return CATEGORY_NAMES[m[1].toUpperCase()] || "";
  return "";
}
function pickCanonicalFromSources(categories) {
  const counts = {};
  for (const c of categories) {
    const canonical = canonicalCategoryFor(c);
    if (!canonical) continue;
    counts[canonical] = (counts[canonical] || 0) + 1;
  }
  let best = "";
  let bestN = 0;
  for (const k of Object.keys(counts)) {
    if (counts[k] > bestN) { best = k; bestN = counts[k]; }
  }
  return best;
}

const apiKey = process.env.NOTION_API_KEY;
const unifiedDbId = UNIFIED_DB_ID;

if (!apiKey) { console.error("pick-l2-sources.mjs: NOTION_API_KEY is required (credentials['notion.integration_token'].apiKey)"); process.exit(1); }

async function queryAll(databaseId) {
  const pages = [];
  let cursor;
  do {
    const res = await fetch(`${NOTION_API}/databases/${databaseId}/query`, {
      method: "POST",
      headers: {
        authorization: `Bearer ${apiKey}`,
        "notion-version": NOTION_VERSION,
        "content-type": "application/json",
      },
      body: JSON.stringify(cursor ? { start_cursor: cursor, page_size: 100 } : { page_size: 100 }),
    });
    if (!res.ok) {
      const body = await res.text().catch(() => "");
      throw new Error(`query ${databaseId} → HTTP ${res.status}: ${body.slice(0, 300)}`);
    }
    const data = await res.json();
    pages.push(...(data.results ?? []));
    cursor = data.has_more ? data.next_cursor : undefined;
  } while (cursor);
  return pages;
}

function typeOf(p) { return p.properties?.Type?.select?.name ?? ""; }
function sourceUrlOf(p) {
  return (
    p.properties?.SourceURLs?.rich_text?.[0]?.plain_text ||
    p.properties?.["Source URLs"]?.url ||
    ""
  ).trim();
}
function asL2(p) {
  return {
    l2PageId: p.id,
    title: p.properties?.Title?.title?.[0]?.plain_text ?? "",
    abstract: p.properties?.Abstract?.rich_text?.[0]?.plain_text ?? "",
    sourceUrl: sourceUrlOf(p),
    category: p.properties?.Category?.rich_text?.[0]?.plain_text ?? "",
    created_time: p.created_time ?? "",
  };
}

// Fisher-Yates shuffle (mirror of handleL3Batch). Nondeterministic by design —
// the GAS picker shuffled too; the sample varies fire-to-fire on purpose.
function shuffle(a) {
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const t = a[i]; a[i] = a[j]; a[j] = t;
  }
  return a;
}

try {
  const pages = await queryAll(unifiedDbId);

  const l2 = pages.filter((p) => typeOf(p) === "explanation").map(asL2);
  const l3 = pages
    .filter((p) => typeOf(p) === "analysis")
    .sort((a, b) => (b.created_time ?? "").localeCompare(a.created_time ?? "")); // newest-first

  // "last run" proxy: the newest analysis row's created_time. No L3 yet → "",
  // which (like an empty L3_LAST_RUN_AT in GAS) treats all recent L2 as fresh,
  // so the very first run isn't blocked.
  const lastRunAt = l3[0]?.created_time ?? "";

  // "recently used" set: the source URLs stamped on the most recent L3 rows.
  // Keyed on URL (each L2's own SourceURL is a stable per-L2 identity).
  const avoid = new Set();
  for (const row of l3.slice(0, L3_AVOID_REUSE_COUNT)) {
    const urls = (row.properties?.SourceURLs?.rich_text?.[0]?.plain_text ?? "")
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
    for (const u of urls) avoid.add(u);
  }

  const cutoff = new Date(Date.now() - L3_RECENT_DAYS * 86400 * 1000).toISOString();
  const recent = l2.filter((p) => (p.created_time || "") >= cutoff);
  const isNew = (p) => !lastRunAt || (p.created_time || "") > lastRunAt;
  const freshL2 = recent.filter(isNew);

  if (freshL2.length === 0) {
    console.log(JSON.stringify({ skip: true, reason: `no new L2 since last L3 (${lastRunAt || "never"})` }));
    process.exit(0);
  }
  if (recent.length < L3_SAMPLE_SIZE) {
    console.log(JSON.stringify({ skip: true, reason: `only ${recent.length} L2 in last ${L3_RECENT_DAYS}d (need ${L3_SAMPLE_SIZE})` }));
    process.exit(0);
  }

  const isReused = (p) => p.sourceUrl && avoid.has(p.sourceUrl);

  // Required pick: one L2 from the fresh pool. Prefer non-reused within fresh.
  const freshNonReused = freshL2.filter((p) => !isReused(p));
  const freshPool = freshNonReused.length > 0 ? freshNonReused : freshL2;
  const required = shuffle(freshPool.slice())[0];

  // Fill the rest from the full recent pool (minus the required pick),
  // preferring non-reused so the sample bridges genuinely distinct sources.
  const fillCandidates = recent.filter((p) => p.l2PageId !== required.l2PageId);
  const fillNonReused = fillCandidates.filter((p) => !isReused(p));
  const fillPool = fillNonReused.length >= L3_SAMPLE_SIZE - 1 ? fillNonReused : fillCandidates;
  const fills = shuffle(fillPool.slice()).slice(0, L3_SAMPLE_SIZE - 1);

  const picked = [required, ...fills];
  const canonicalCategory = pickCanonicalFromSources(picked.map((p) => p.category));
  const sourceUrls = picked.map((p) => p.sourceUrl).filter(Boolean).join(", ");

  console.log(
    JSON.stringify({
      sources: picked.map(({ l2PageId, title, abstract, sourceUrl, category }) => ({
        l2PageId,
        title,
        abstract,
        sourceUrl,
        category,
      })),
      canonicalCategory,
      sourceUrls,
      requiredNewL2Id: required.l2PageId,
    }),
  );
  process.exit(0);
} catch (err) {
  console.error(`pick-l2-sources.mjs: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

#!/usr/bin/env node
// Deterministic L3-analysis writer — invoked by the CCR agent-runner after it
// has *synthesised* the analysis markdown from the picked L2 sample. The LLM
// owns the judgment (the inductive synthesis); this script owns the
// structurally-exact Notion write so the failure class "LLM hand-edits the page
// JSON and guesses the schema wrong" cannot recur. Sibling of
// article-level2/publish-notion.mjs — same contract, Type=analysis instead of
// explanation, plus the L3-specific source/category shape.
//
// It POSTs a new page into the unified Articles DB using the injected Notion
// integration token. The row carries Author + Type=analysis + Status=ready
// (queued; the GAS L4 batch generates the hero image and flips it to published)
// so it lands on kohuehara.xyz and newsletter/pipeline/fetch-notion.mjs surfaces the byline
// (AuthorChip).
//
// L3 differs from L2 on two writes (mirror of newsletter/gas/src/Code.gs handleL3Create):
//   • SourceURLs   — the COMMA-JOINED source L2 URLs (not a single URL). This is
//     both the "References" surface and the reuse-avoidance key pick-l2-sources
//     reads back on the next fire.
//   • CategoriesMulti — TWO tags: the majority A–E canonical bucket of the source
//     L2s (--category) + an optional free-form "テーマ1 × テーマ2" synthesis theme
//     (--theme). Category (rich_text) carries the canonical bucket.
//
// The CCR session never reads Secrets Manager: NOTION_API_KEY arrives inline
// from the task's `credentials["notion.integration_token"].apiKey`. The target
// DB id is NOT secret, so it's a constant below — overridable by NOTION_DB_ID.
//
// W-1 (editorial integrity): refuses an empty / too-short body, rejects
// LLM-failure prelude artefacts, and rejects a body whose last line looks cut
// off mid-content (C-1), failing loud (exit 2) rather than landing a degraded
// article. The floor is higher than L2's: an L3 synthesis is ~3000–4000 字, so
// anything under MIN_BODY_CHARS is a truncated generation. The cut-off check
// is the canonical heuristic from scripts/lib/truncation.mjs — with the GAS
// cron paused this skill is the generation path, so the R-5-equivalent guard
// must fire here, per-article, rather than only at the R-10 deploy gate.
//
// Body is read from a FILE (not an arg) so multi-line / Unicode prose can't be
// mangled by shell quoting. The first `# ` line is the page Title, stripped from
// the body blocks.
//
// Usage:
//   NOTION_API_KEY="<credentials['notion.integration_token'].apiKey>" \
//     node workforce/skills/article-level3/publish-notion.mjs \
//       --author elena --type analysis --status ready \
//       --body-file /tmp/l3-article.md \
//       --abstract-file /tmp/l3-abstract.txt \
//       --source-urls "https://a, https://b, https://c" \
//       --category "B" \                  # majority A–E bucket from the picker
//       [--theme "担い手の交代 × ツールの民主化"]   # free-form synthesis theme
//
// Exit codes:
//   0  — page created
//   1  — bad args / env / body-file unreadable / no H1 title
//   2  — W-1 editorial guard failed (empty/short body, LLM-artefact prelude,
//        or cut-off last line)
//   3  — Notion API error / network error

import { readFileSync } from "node:fs";
import { isTruncatedMarkdown, lastNonEmptyLine } from "../../../scripts/lib/truncation.mjs";

const NOTION_VERSION = "2022-06-28";
const NOTION_API = "https://api.notion.com/v1";
const UNIFIED_DB_ID = process.env.NOTION_DB_ID || "34fd0f0b-e61e-817a-9f6b-dc65b0d5b4cc";
// An L3 analysis is ~3000–4000 字; floor well above that to catch truncation
// while tolerating a terse synthesis. Higher than L2's 200-char floor.
const MIN_BODY_CHARS = 400;
const ARTEFACT_PRELUDE =
  /^\s*(as an ai|here is|here's|i apologize|i'm sorry|certainly!|sure,|of course)/i;

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

// Canonical A–E bucket — mirror of newsletter/gas/src/Code.gs CATEGORY_NAMES +
// canonicalCategoryFor. The picker already computed the majority bucket; this
// re-canonicalises so a bare letter ("B") or a canonical label both resolve.
const CATEGORY_NAMES = {
  A: "A: AI Hyper-productivity",
  B: "B: Role Blurring",
  C: "C: New Roles/FDE",
  D: "D: Big Tech Layoffs & AI Pivot",
  E: "E: Rethinking SDLC",
};
function canonicalCategory(text) {
  const trimmed = (text || "").trim();
  if (!trimmed) return "";
  if (/^[A-E]$/i.test(trimmed)) return CATEGORY_NAMES[trimmed.toUpperCase()] || "";
  const m = trimmed.match(/^([A-E])[\s:：][\s\S]*$/i);
  if (m) return CATEGORY_NAMES[m[1].toUpperCase()] || "";
  return ""; // free-form / unmappable → leave canonical unset (don't guess)
}

const apiKey = process.env.NOTION_API_KEY;
const databaseId = UNIFIED_DB_ID;
const author = arg("author");
const articleType = arg("type") ?? "analysis";
const status = arg("status") ?? "ready";
const bodyFile = arg("body-file");
const sourceUrls = arg("source-urls");      // comma-joined source L2 URLs
const category = arg("category");           // majority A–E letter or canonical label
const theme = arg("theme");                 // optional free-form synthesis theme
const abstractFile = arg("abstract-file");

const VALID_STATUS = new Set(["draft", "ready", "published", "archived"]);

if (!apiKey) { console.error("publish-notion.mjs: NOTION_API_KEY env var is required (from credentials['notion.integration_token'].apiKey)"); process.exit(1); }
if (!author) { console.error("publish-notion.mjs: --author <slug> is required"); process.exit(1); }
if (articleType !== "explanation" && articleType !== "analysis") {
  console.error(`publish-notion.mjs: --type must be explanation|analysis (got "${articleType}")`);
  process.exit(1);
}
if (!VALID_STATUS.has(status)) {
  console.error(`publish-notion.mjs: --status must be one of ${[...VALID_STATUS].join("|")} (got "${status}")`);
  process.exit(1);
}
if (!bodyFile) { console.error("publish-notion.mjs: --body-file <path> is required"); process.exit(1); }

let body;
try {
  body = readFileSync(bodyFile, "utf8");
} catch (err) {
  console.error(`publish-notion.mjs: cannot read --body-file "${bodyFile}": ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
}

let abstract = "";
if (abstractFile) {
  try {
    abstract = readFileSync(abstractFile, "utf8").trim();
  } catch (err) {
    console.error(`publish-notion.mjs: cannot read --abstract-file "${abstractFile}": ${err instanceof Error ? err.message : String(err)}`);
    process.exit(1);
  }
}

// ── W-1 editorial guards (fail loud, do not publish) ───────────────────────
const trimmed = body.trim();
if (trimmed.length < MIN_BODY_CHARS) {
  console.error(`publish-notion.mjs: body is ${trimmed.length} chars (< ${MIN_BODY_CHARS}) — refusing to publish a truncated/empty analysis (W-1)`);
  process.exit(2);
}
if (ARTEFACT_PRELUDE.test(trimmed.slice(0, 50))) {
  console.error(`publish-notion.mjs: body opens with an LLM-failure prelude — refusing to publish (W-1)`);
  process.exit(2);
}
if (isTruncatedMarkdown(trimmed)) {
  console.error(`publish-notion.mjs: body looks cut off mid-content (last line: "${lastNonEmptyLine(trimmed)}") — refusing to publish a truncated analysis (W-1)`);
  process.exit(2);
}

// First `# ` line is the title; strip it from the body blocks.
const lines = trimmed.split(/\r?\n/);
const h1Idx = lines.findIndex((l) => /^#\s+\S/.test(l));
if (h1Idx === -1) {
  console.error("publish-notion.mjs: body has no `# Title` H1 on its own line — the L3 format requires one (exit 1)");
  process.exit(1);
}
const title = lines[h1Idx].replace(/^#\s+/, "").trim();
const bodyLines = lines.slice(0, h1Idx).concat(lines.slice(h1Idx + 1));

const children = markdownToBlocks(bodyLines.join("\n"));

// Property names mirror the live unified Articles DB exactly (same contract as
// the GAS L3 write): Title (title), Type/Status (select), Author/SourceURLs as
// rich_text, Date.
const properties = {
  Title: { title: [{ text: { content: title.slice(0, 2000) } }] },
  Author: { rich_text: [{ text: { content: author } }] },
  Type: { select: { name: articleType } },
  Status: { select: { name: status } },
  Date: { date: { start: new Date().toISOString().slice(0, 10) } },
};

// SourceURLs — comma-joined source L2 URLs. This is what pick-l2-sources reads
// back to avoid re-synthesising the same sample on the next fire, so always set
// it when sources are known.
if (sourceUrls) properties.SourceURLs = { rich_text: [{ text: { content: sourceUrls.slice(0, 2000) } }] };

if (abstract) properties.Abstract = { rich_text: [{ text: { content: abstract.slice(0, 2000) } }] };

// Category + CategoriesMulti — the canonical bucket (majority vote of sources)
// plus an optional free-form synthesis theme, mirroring the GAS L3 two-tag
// write. A free-form / unmappable --category leaves the canonical unset rather
// than guessing; the theme tag is still added when present.
const canonical = canonicalCategory(category);
const tags = [];
if (canonical) tags.push(canonical);
if (theme && theme.trim()) tags.push(theme.trim().slice(0, 100));
if (canonical) properties.Category = { rich_text: [{ text: { content: canonical } }] };
if (tags.length) properties.CategoriesMulti = { multi_select: tags.map((name) => ({ name })) };

try {
  const res = await fetch(`${NOTION_API}/pages`, {
    method: "POST",
    headers: {
      authorization: `Bearer ${apiKey}`,
      "notion-version": NOTION_VERSION,
      "content-type": "application/json",
    },
    body: JSON.stringify({ parent: { database_id: databaseId }, properties, children }),
  });
  const text = await res.text().catch(() => "");
  if (res.ok) {
    let url = "";
    try { url = JSON.parse(text).url ?? ""; } catch { /* non-JSON ok body */ }
    console.log(`publish-notion.mjs: created — Author=${author} Type=${articleType} Status=${status} "${title}" ${url}`);
    process.exit(0);
  }
  if (res.status === 401 || res.status === 403) {
    console.error(`publish-notion.mjs: auth rejected (HTTP ${res.status}) — project credential bag misconfigured: ${text.slice(0, 400)}`);
    process.exit(2);
  }
  console.error(`publish-notion.mjs: Notion API error (HTTP ${res.status}): ${text.slice(0, 400)}`);
  process.exit(3);
} catch (err) {
  console.error(`publish-notion.mjs: fetch failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

// Minimal Markdown → Notion blocks. Handles H1-3, bullet lists, and paragraphs
// (blank-line separated). Notion accepts ≤ 100 children per request; we cap
// conservatively. Per-block rich_text is capped at 2000 chars (Notion's limit).
function markdownToBlocks(md) {
  const out = [];
  let para = [];
  const flushPara = () => {
    if (para.length === 0) return;
    pushText("paragraph", para.join(" "));
    para = [];
  };
  const pushText = (type, content) => {
    out.push({
      object: "block",
      type,
      [type]: { rich_text: [{ type: "text", text: { content: content.slice(0, 2000) } }] },
    });
  };
  for (const raw of md.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === "") { flushPara(); continue; }
    let m;
    if ((m = line.match(/^###\s+(.+)/))) { flushPara(); pushText("heading_3", m[1]); }
    else if ((m = line.match(/^##\s+(.+)/))) { flushPara(); pushText("heading_2", m[1]); }
    else if ((m = line.match(/^#\s+(.+)/))) { flushPara(); pushText("heading_2", m[1]); }
    else if ((m = line.match(/^[-*]\s+(.+)/))) { flushPara(); pushText("bulleted_list_item", m[1]); }
    else { para.push(line); }
  }
  flushPara();
  return out.slice(0, 100);
}

#!/usr/bin/env node
// daily-research/post.mjs — deterministic write for the "daily-research" Cadence,
// invoked by the CCR agent-runner AFTER it has *generated* the content. The LLM
// owns the judgment (the researched observation body); this script owns the
// structurally-exact write so the failure class "LLM hand-edits JSON and guesses
// the schema wrong" cannot recur. Modeled on workforce/skills/feed-post/post-feed.mjs
// and workforce/skills/grid-watch/post.mjs — the canonical Cadence write.
//
// daily-research is the generic, persona-agnostic research cadence: one skill,
// many beat personas. The *beat* lives on the persona (system.md / JD), not here;
// this script's only job is the authenticated write. It POSTs to the same /feed
// endpoint with the project-scoped credential injected per-fire
// (credentials['workforce.feed_write_token']). It does NOT touch the repo, does
// NOT open a PR — the write lands directly in the backing store. No human gate.
//
// Body is read from a FILE (not an arg) so multi-line / Unicode prose can't be
// mangled by shell quoting. The write CREDENTIAL is injected per-fire; the
// endpoint URL is NOT a secret and is the single source of truth right here.
//
// Usage:
//   FEED_WRITE_TOKEN=<from credentials['workforce.feed_write_token']> \
//     node workforce/skills/daily-research/post.mjs \
//       --agent <slug> --body-file /tmp/body.md [--skill-version 0.1.0]
//
// Exit codes:
//   0  — written (HTTP 2xx)
//   1  — bad args / env / body-file unreadable
//   2  — endpoint rejected (HTTP 401 auth / 422 validation)
//   3  — network / unexpected error

import { readFileSync } from "node:fs";

// Single source of truth for this Cadence's write endpoint. Override with
// FEED_WRITE_TOKEN_API_URL only for non-prod / dev stages.
const DEFAULT_API_URL = "https://sjhikazsf9.execute-api.us-west-2.amazonaws.com/prod/feed";

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

const apiUrl = process.env["FEED_WRITE_TOKEN_API_URL"] || DEFAULT_API_URL;
const token = process.env["FEED_WRITE_TOKEN"];
const agent = arg("agent");
const bodyFile = arg("body-file");
const skillVersion = arg("skill-version");

if (!token) { console.error("post.mjs: FEED_WRITE_TOKEN env var is required (from credentials['workforce.feed_write_token'])"); process.exit(1); }
if (!agent) { console.error("post.mjs: --agent <slug> is required"); process.exit(1); }
if (!bodyFile) { console.error("post.mjs: --body-file <path> is required"); process.exit(1); }
if (apiUrl.startsWith("TODO_")) { console.error("post.mjs: DEFAULT_API_URL is still a scaffold placeholder — set the real endpoint"); process.exit(1); }

let body;
try {
  body = readFileSync(bodyFile, "utf8");
} catch (err) {
  console.error(`post.mjs: cannot read --body-file "${bodyFile}": ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
}

// W-1 editorial guard (client side; the endpoint should re-run it server side).
// A degraded body fails loud here rather than landing on the backing store.
const ARTEFACTS = ["as an ai", "i apologize", "i'm sorry", "certainly!", "sure, ", "here is the", "here's the"];
const head = body.trimStart().slice(0, 50).toLowerCase();
if (body.trim().length === 0) { console.error("post.mjs: body is empty (W-1)"); process.exit(1); }
if (ARTEFACTS.some((a) => head.startsWith(a))) { console.error(`post.mjs: body opens with an LLM-failure artefact (W-1): "${head}"`); process.exit(1); }

// POST /feed requires a `kind` from the Epic-011 set {reflection, friction,
// improvement, observation}. A daily-research digest is beat-noticing, neither
// friction nor proposal — it is ALWAYS an observation; the constant lives here
// (the deterministic layer) so the LLM cannot mis-tag it.
const payload = { agent_slug: agent, kind: "observation", body };
if (skillVersion) payload.skill_version = skillVersion;

console.error(`post.mjs: POST ${apiUrl}`);

try {
  const res = await fetch(apiUrl, {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${token}` },
    body: JSON.stringify(payload),
  });
  const text = await res.text().catch(() => "");
  if (res.status >= 200 && res.status < 300) {
    console.log(`post.mjs: written — ${text}`);
    process.exit(0);
  }
  if (res.status === 401 || res.status === 422) {
    console.error(`post.mjs: rejected (HTTP ${res.status}): ${text.slice(0, 400)}`);
    process.exit(2);
  }
  console.error(`post.mjs: unexpected HTTP ${res.status}: ${text.slice(0, 400)}`);
  process.exit(3);
} catch (err) {
  console.error(`post.mjs: fetch failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

