  process.exit(1);
}

// W-1 editorial guard (client side; the endpoint should re-run it server side).
// A degraded body fails loud here rather than landing on the backing store.
const ARTEFACTS = ["as an ai", "i apologize", "i'm sorry", "certainly!", "sure, ", "here is the", "here's the"];
const head = body.trimStart().slice(0, 50).toLowerCase();
if (body.trim().length === 0) { console.error("post.mjs: body is empty (W-1)"); process.exit(1); }
if (ARTEFACTS.some((a) => head.startsWith(a))) { console.error(`post.mjs: body opens with an LLM-failure artefact (W-1): "${head}"`); process.exit(1); }

// POST /feed requires a `kind` from the Epic-011 set {reflection, friction,
// improvement, observation}. An india-grid-watch digest is beat-noticing,
// neither friction nor proposal — it is ALWAYS an observation; the constant
// lives here (the deterministic layer) so the LLM cannot mis-tag it.
const payload = { agent_slug: agent, kind: "observation", body };
if (skillVersion) payload.skill_version = skillVersion;

console.error(`post.mjs: POST ${apiUrl}`);

try {
  const res = await fetch(apiUrl, {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${token}` },
    body: JSON.stringify(payload),
  });
  const text = await res.text().catch(() => "");
  if (res.status >= 200 && res.status < 300) {
    console.log(`post.mjs: written — ${text}`);
    process.exit(0);
  }
  if (res.status === 401 || res.status === 422) {
    console.error(`post.mjs: rejected (HTTP ${res.status}): ${text.slice(0, 400)}`);
    process.exit(2);
  }
  console.error(`post.mjs: unexpected HTTP ${res.status}: ${text.slice(0, 400)}`);
  process.exit(3);
} catch (err) {
  console.error(`post.mjs: fetch failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(3);
}

#!/usr/bin/env node
// Deterministic legal-amendment-review-committee WRITE script — the ONLY write
// this skill performs. It posts ONE `event: COMMENT` pull-request review to a
// target PR, carrying the committee's verdict (APPROVE/REJECT recommendation +
// follow-ups).
//
// W-5 / R-N9 by construction: the single fetch below targets
// `POST /repos/{owner}/{repo}/pulls/{n}/reviews` with `event: "COMMENT"`,
// HARD-CODED. There is no code path that sends APPROVE / REQUEST_CHANGES, that
// merges, pushes a branch, or opens a PR. The committee recommends; humans gate.
//
// The repo (owner/repo) is read from the in-repo project.json; the github.token
// is injected per-fire from the active project's credential bag and read here
// from GITHUB_TOKEN. The verdict body is read from a FILE so multi-line /
// Unicode prose can't be mangled by shell quoting.
//
// Usage:
//   GITHUB_TOKEN=<credentials['github.token'].token> \
//     node workforce/skills/legal-amendment-review-committee/post-review.mjs \
//       --project asp-cloud --pr 42 --body-file /tmp/larc-verdict-42.md
//
// Exit codes:
//   0  — review created (HTTP 200)
//   1  — bad args / project.json missing / body-file unreadable or empty
//   2  — endpoint rejected (auth / 4xx)
//   3  — network / unexpected error

import { readFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";

const GH_API = "https://api.github.com";
const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..", "..");

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

// Resolve { owner, repo } from workforce/projects/{id}/project.json:github.
function projectRepo(repoRoot, projectId) {
  const path = join(repoRoot, "workforce", "projects", projectId, "project.json");
  let json;
  try {
    json = JSON.parse(readFileSync(path, "utf8"));
  } catch {
    throw new Error(`project.json unreadable for project "${projectId}" at ${path}`);
  }
  const gh = json.github;
  if (!gh || typeof gh.owner !== "string" || typeof gh.repo !== "string") {
    throw new Error(`project "${projectId}" has no github.{owner,repo} — not an external git project`);
  }
  return { owner: gh.owner, repo: gh.repo };
}

async function main() {
  const projectId = arg("project");
  const prNumber = arg("pr");
  const bodyFile = arg("body-file");
  const token = process.env.GITHUB_TOKEN;

  if (!projectId) die(1, "--project <id> is required");
  if (!prNumber || !/^\d+$/.test(prNumber)) die(1, "--pr <number> is required (positive integer)");
  if (!bodyFile) die(1, "--body-file <path> is required");
  if (!token) die(2, "GITHUB_TOKEN env is required (from credentials['github.token'].token)");

  let owner, repo, body;
  try {
    ({ owner, repo } = projectRepo(REPO_ROOT, projectId));
  } catch (e) {
    die(1, e.message);
  }
  try {
    body = readFileSync(bodyFile, "utf8");
  } catch {
    die(1, `body-file unreadable: ${bodyFile}`);
  }
  if (body.trim().length === 0) {
    die(1, "body-file is empty — refusing to post an empty committee verdict (W-4)");
  }

  let res;
  try {
    res = await fetch(`${GH_API}/repos/${owner}/${repo}/pulls/${prNumber}/reviews`, {
      method: "POST",
      headers: {
        authorization: `Bearer ${token}`,
        accept: "application/vnd.github+json",
        "content-type": "application/json",
        "x-github-api-version": "2022-11-28",
        "user-agent": "kohuehara-workforce",
      },
      // event is COMMENT, hard-coded: a recommendation, never a merge-gating verdict.
      body: JSON.stringify({ body, event: "COMMENT" }),
    });
  } catch (e) {
    die(3, `network error: ${e instanceof Error ? e.message : String(e)}`);
  }
  if (res.status === 200) {
    const json = await res.json().catch(() => ({}));
    console.log(`larc-post: committee verdict posted to ${owner}/${repo}#${prNumber} (review ${json.id ?? "?"})`);
    process.exit(0);
  }
  const text = await res.text().catch(() => "");
  die(res.status < 500 ? 2 : 3, `POST review → ${res.status}: ${text.slice(0, 300)}`);
}

function die(code, msg) {
  console.error(`larc-post: ${msg}`);
  process.exit(code);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  main().catch((e) => die(3, e instanceof Error ? e.message : String(e)));
}

export { projectRepo };

#!/usr/bin/env node
// Wire maya's `legal-amendment-review-committee` binding via
// PATCH /agents/maya (ADR-0007: bindings are DDB config, agents-api is the
// single writer — each PATCH is validated (R8 against the SKILL# rows) and
// lands its own AUDIT item; write = live, no deploy).
//
// One agent, one binding: maya (the committee chair) ← the
// legal-amendment-review-committee skill, executor=claude-code-routine,
// scheduler=manual (non-periodic; the amendment under review is supplied
// per invocation — there is NO cron). Mirrors the shape documented in
// workforce/docs/routines/legal-amendment-review-committee.md.
//
// PREREQ (fail-loud if unmet): the PR adding workforce/skills/
// legal-amendment-review-committee must be MERGED and the data-plane deploy
// finished — wf-seed-skills creates the SKILL#legal-amendment-review-
// committee row (owners=[maya]) post-deploy, and the R8 write-time check
// validates this binding against that row. Running before the seed 422s
// with R8-binding-skill-exists (no partial write).
//
// Idempotent: maya's existing bindings are preserved (append-only —
// binding_idx is load-bearing); if the committee skill is already bound,
// this skips rather than duplicating it.
//
// Usage:
//   node workforce/skills/legal-amendment-review-committee/wire-binding.mjs --dry-run
//   aws-vault exec <profile> -- node workforce/skills/legal-amendment-review-committee/wire-binding.mjs

import { spawnSync } from "node:child_process";

const API_BASE = (
  process.env.WF_AGENTS_API_BASE ??
  "https://sjhikazsf9.execute-api.us-west-2.amazonaws.com/prod"
).replace(/\/+$/, "");
const REGION = process.env.AWS_REGION ?? "us-west-2";
const DRY_RUN = process.argv.includes("--dry-run");

const AGENT = "maya";
const SKILL = "legal-amendment-review-committee";

// claude-code-routine + manual is the declarative-pending shape (the
// routine_spec is the load-bearing artefact; operator-invoked today). No
// cron: this committee convenes on demand, not on a schedule.
const BINDING = {
  skill: SKILL,
  executor: "claude-code-routine",
  trigger: { scheduler: "manual" },
  routine_spec: `workforce/docs/routines/${SKILL}.md`,
  project_id: "asp-cloud",
  note: "VP-tier+ committee; reviews asp-cloud governance amendments; comment-only (W-5/R-N9).",
};

function curlJson(method, path, body) {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_SESSION_TOKEN } = process.env;
  const args = ["-sS", "-X", method, "-H", "content-type: application/json", "-w", "\n%{http_code}", `${API_BASE}${path}`];
  if (method !== "GET") {
    if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
      throw new Error("AWS credentials missing — run under `aws-vault exec <profile> --`");
    }
    args.push("--aws-sigv4", `aws:amz:${REGION}:execute-api`, "--user", `${AWS_ACCESS_KEY_ID}:${AWS_SECRET_ACCESS_KEY}`);
    if (AWS_SESSION_TOKEN) args.push("-H", `x-amz-security-token: ${AWS_SESSION_TOKEN}`);
    args.push("--data-binary", "@-");
  }
  const res = spawnSync("curl", args, { input: method === "GET" ? undefined : JSON.stringify(body), encoding: "utf8" });
  if (res.status !== 0) throw new Error(`curl failed: ${res.stderr}`);
  const out = res.stdout;
  const nl = out.lastIndexOf("\n");
  return { status: Number(out.slice(nl + 1)), json: out.slice(0, nl) ? JSON.parse(out.slice(0, nl)) : undefined };
}

const cur = await (await fetch(`${API_BASE}/agents/${AGENT}`)).json();
if (!Array.isArray(cur.bindings)) {
  console.error(`✗ ${AGENT}: GET returned no bindings[] (agent registered?)`);
  process.exit(1);
}
if (cur.bindings.some((b) => b.skill === SKILL)) {
  console.log(`- ${AGENT}: ${SKILL} already bound, skipped`);
  process.exit(0);
}

// Append-only: existing bindings keep their binding_idx.
const next = [...cur.bindings, BINDING];
if (DRY_RUN) {
  console.log(`[dry-run] ${AGENT}: would PATCH bindings -> +1 (${SKILL} @ manual); total ${next.length}`);
  process.exit(0);
}

const { status, json } = curlJson("PATCH", `/agents/${AGENT}`, { bindings: next });
if (status === 200) {
  console.log(`✓ ${AGENT}: bound ${SKILL} (claude-code-routine + manual; project=asp-cloud)`);
  console.log("Done — write = live (ADR-0007). Invoke the committee on demand; there is no cron.");
} else {
  console.error(`✗ ${AGENT}: HTTP ${status} ${JSON.stringify(json)}`);
  if (status === 422) {
    console.error("  422 usually means the SKILL# row isn't seeded yet (R8-binding-skill-exists) —");
    console.error("  ensure the skill PR is merged AND the data-plane deploy + wf-seed-skills have run.");
  }
  process.exit(1);
}

