//
// Locks the operator directive (2026-06-21): a pr-autopilot hand-off to a human
// ALWAYS carries the autopilot:needs-human label. resolveLabels is the mechanical
// half — it must add ESCALATION_LABEL whenever the verdict escalates (the
// --needs-human flag OR the hidden body marker), and never on a plain routing
// comment.
import { describe, it, expect } from "vitest";
import { resolveLabels, NEEDS_HUMAN_MARKER, REVIEWED_MARKER } from "./pr-autopilot-post.mjs";
import { ESCALATION_LABEL, REVIEWED_LABEL } from "./pr-merge.mjs";

describe("resolveLabels — escalation always carries the label", () => {
  it("a plain routing comment (no flag, no marker) gets no escalation label", () => {
    expect(resolveLabels([], { needsHuman: false, body: "**Nadia — cycle 1.**" })).toEqual([]);
  });

  it("--needs-human forces ESCALATION_LABEL even with no --label values", () => {
    expect(resolveLabels([], { needsHuman: true, body: "verdict" })).toEqual([ESCALATION_LABEL]);
  });

  it("the hidden body marker forces ESCALATION_LABEL even if --needs-human was forgotten", () => {
    const body = `L0/L1 change — operator's final call.\n\n${NEEDS_HUMAN_MARKER}\n`;
    expect(resolveLabels([], { needsHuman: false, body })).toEqual([ESCALATION_LABEL]);
  });

  it("merges explicit --label values and de-dupes the canonical label", () => {
    const out = resolveLabels(["governance", ESCALATION_LABEL], {
      needsHuman: true,
      body: NEEDS_HUMAN_MARKER,
    });
    expect(out).toContain("governance");
    expect(out.filter((l) => l === ESCALATION_LABEL)).toHaveLength(1);
  });

  it("extra --label values without escalation do NOT add the canonical label", () => {
    expect(resolveLabels(["needs-rebase"], { needsHuman: false, body: "" })).toEqual(["needs-rebase"]);
  });

  it("the marker constant is the canonical hidden token", () => {
    expect(NEEDS_HUMAN_MARKER).toBe("<!-- autopilot:needs-human -->");
  });
});

// Locks the operator directive (2026-06-23): a 🟢 unanimous-green PR handed off
// to a human only because of a human gate (L0/L1 / no delegation) ALSO carries
// autopilot:reviewed, so the operator can find the merge-ready subset. reviewed
// is an independent signal — it never implies escalation and vice versa.
describe("resolveLabels — a green, merge-ready hand-off is flagged reviewed", () => {
  it("--reviewed adds REVIEWED_LABEL alongside ESCALATION_LABEL on a green-L0/L1 hand-off", () => {
    const out = resolveLabels([], { needsHuman: true, reviewed: true, body: "verdict" });
    expect(out).toContain(ESCALATION_LABEL);
    expect(out).toContain(REVIEWED_LABEL);
  });

  it("the hidden reviewed marker adds REVIEWED_LABEL even if --reviewed was forgotten", () => {
    const body = `🟢 consensus, but touches L0/L1.\n\n${NEEDS_HUMAN_MARKER}\n${REVIEWED_MARKER}\n`;
    const out = resolveLabels([], { needsHuman: false, reviewed: false, body });
    expect(out).toContain(ESCALATION_LABEL);
    expect(out).toContain(REVIEWED_LABEL);
  });

  it("a 🔴 / non-consensus escalation gets needs-human but NOT reviewed", () => {
    expect(resolveLabels([], { needsHuman: true, reviewed: false, body: "🔴 blocking" })).toEqual([ESCALATION_LABEL]);
  });

  it("reviewed is independent of escalation — reviewed alone never adds needs-human", () => {
    expect(resolveLabels([], { needsHuman: false, reviewed: true, body: "" })).toEqual([REVIEWED_LABEL]);
  });

  it("a plain routing comment gets neither label", () => {
    expect(resolveLabels([], { needsHuman: false, reviewed: false, body: "**Nadia — cycle 1.**" })).toEqual([]);
  });

  it("the reviewed marker constant is the canonical hidden token", () => {
    expect(REVIEWED_MARKER).toBe("<!-- autopilot:reviewed -->");
  });
});

#!/usr/bin/env node
// Deterministic pr-autopilot POST script — posts ONE routing/verdict comment to
// a PR's issue-comment thread, and (optionally) stamps escalation labels on the
// PR so a human can find the hand-off queue.
//
// R-N9 / W-5 by construction: it writes ONLY an issue comment
// (`POST /repos/{owner}/{repo}/issues/{n}/comments`) and, with --label, issue
// labels (`POST /repos/{owner}/{repo}/issues/{n}/labels`). There is no code path
// that approves, requests-changes, merges, pushes a branch, or opens a PR.
// The external git surface stays comment+label only — agents never gate merges.
//
// The repo (owner/repo) is read from the in-repo project.json; the
// github.token is injected per-fire via the (project × agent × skill)
// binding's project linkage and read here from GITHUB_TOKEN. The comment
// body is read from a FILE so multi-line / Unicode prose can't be mangled
// by shell quoting.
//
// Usage:
//   GITHUB_TOKEN=<credentials['github.token'].token> \
//     node workforce/skills/pr-autopilot/pr-autopilot-post.mjs \
//       --project asp-cloud --pr 42 --body-file /tmp/route-body-42.md \
//       [--needs-human] [--label <name>]   # see escalation rule below
//
// ESCALATION ALWAYS CARRIES THE LABEL (operator directive 2026-06-21). Any
// comment that hands a PR to a human — a 🟢 PR touching the target's governance
// L0/L1, a 🔴 verdict, a non-consensus PR, a no-delegation hand-off — MUST be
// stamped `autopilot:needs-human` so the operator finds the queue with
// `is:open label:autopilot:needs-human`. This script applies that label from
// EITHER signal, so a hand-off can never reach a human un-labelled even if one
// is forgotten:
//   - `--needs-human` flag, OR
//   - the hidden marker `<!-- autopilot:needs-human -->` embedded in the verdict
//     body (the SKILL.md escalation template carries it).
// The canonical label name is single-sourced from pr-merge.mjs (ESCALATION_LABEL),
// the same constant the engine stamps on escalation issues — one queue, one name.
//
// REVIEWED (merge-ready) hand-offs (operator directive 2026-06-23). When the
// hand-off is a 🟢 unanimous-green PR held back only by a human gate (the
// target's L0/L1 boundary, or a missing R-N10 delegation), it ALSO carries
// `autopilot:reviewed` — so the operator can tell "reviewed + merge-ready, my
// final call" apart from a 🔴 / cycle-capped / non-consensus escalation that
// still needs work. Stamped from EITHER `--reviewed` OR the hidden body marker
// `<!-- autopilot:reviewed -->`. A 🔴 / non-consensus escalation gets only
// `autopilot:needs-human`, never this.
//
// Extra `--label <name>` values (repeatable) are merged in. Routing comments
// (cycle 1) carry neither flag nor marker, so they stay unlabelled. Missing
// labels are auto-created (each with its own colour/description).
//
// Exit codes:
//   0  — comment created (HTTP 201); labels best-effort
//   1  — bad args / project.json missing / body-file unreadable
//   2  — endpoint rejected (auth/4xx)
//   3  — network / unexpected error

import { readFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";
import { projectRepo } from "./pr-autopilot-scan.mjs";
import { ESCALATION_LABEL, REVIEWED_LABEL } from "./pr-merge.mjs";

const GH_API = "https://api.github.com";
const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..", "..");

/** Per-label colour + description used when auto-creating a label the target
 *  repo lacks. Unknown labels (explicit --label values) fall back to the
 *  escalation colour. Single object so the two canonical labels never drift. */
const LABEL_META = {
  [ESCALATION_LABEL]: {
    color: "b60205", // red — "an autopilot decision needs a human"
    description: "Autopilot handed this off — a human's call (merge / governance L0/L1 / blocked).",
  },
  [REVIEWED_LABEL]: {
    color: "0e8a16", // green — "reviewed to 🟢 consensus, merge-ready"
    description: "Autopilot reviewed this to a 🟢 unanimous-green consensus; merge-ready, held only by a human gate (L0/L1 / delegation) — the operator merges.",
  },
};
const FALLBACK_LABEL_META = LABEL_META[ESCALATION_LABEL];

/** Hidden marker the SKILL.md hand-off/escalation verdict template embeds. Its
 *  presence in the comment body forces ESCALATION_LABEL even if --needs-human
 *  was omitted — the mechanical half of "escalation ALWAYS carries the label". */
export const NEEDS_HUMAN_MARKER = "<!-- autopilot:needs-human -->";

/** Hidden marker for a 🟢 merge-ready hand-off. Its presence (or --reviewed)
 *  adds REVIEWED_LABEL alongside ESCALATION_LABEL — the mechanical half of
 *  "a green, human-gated PR is flagged reviewed even if the flag is dropped". */
export const REVIEWED_MARKER = "<!-- autopilot:reviewed -->";

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : undefined;
}

function flag(name) {
  return process.argv.includes(`--${name}`);
}

/** All values passed via repeated --label flags. */
function labelArgs() {
  const out = [];
  for (let i = 0; i < process.argv.length; i++) {
    if (process.argv[i] === "--label" && process.argv[i + 1]) out.push(process.argv[i + 1]);
  }
  return [...new Set(out)];
}

/** The label set to stamp. Exported + pure so the invariants are unit-tested,
 *  not merely documented:
 *   - any hand-off to a human carries ESCALATION_LABEL — added whenever the
 *     verdict escalates (the --needs-human flag OR the hidden body marker);
 *   - a 🟢 merge-ready hand-off ALSO carries REVIEWED_LABEL (the --reviewed
 *     flag OR the hidden reviewed marker) — and reviewed never implies escalated
 *     and vice versa; each is its own signal, on top of any explicit --label. */
export function resolveLabels(rawLabels, { needsHuman = false, reviewed = false, body = "" } = {}) {
  const out = [...rawLabels];
  if (needsHuman || body.includes(NEEDS_HUMAN_MARKER)) out.push(ESCALATION_LABEL);
  if (reviewed || body.includes(REVIEWED_MARKER)) out.push(REVIEWED_LABEL);
  return [...new Set(out)];
}

async function gh(token, method, path, body) {
  return fetch(`${GH_API}${path}`, {
    method,
    headers: {
      authorization: `Bearer ${token}`,
      accept: "application/vnd.github+json",
      "content-type": "application/json",
      "x-github-api-version": "2022-11-28",
      "user-agent": "kohuehara-workforce",
    },
    body: body ? JSON.stringify(body) : undefined,
  });
}

async function main() {
  const projectId = arg("project");
  const prNumber = arg("pr");
  const bodyFile = arg("body-file");
  const token = process.env.GITHUB_TOKEN;

  if (!projectId) die(1, "--project <id> is required");
  if (!prNumber || !/^\d+$/.test(prNumber)) die(1, "--pr <number> is required (positive integer)");
  if (!bodyFile) die(1, "--body-file <path> is required");
  if (!token) die(2, "GITHUB_TOKEN env is required (from credentials['github.token'].token)");

  let owner, repo, body;
  try {
    ({ owner, repo } = projectRepo(REPO_ROOT, projectId));
  } catch (e) {
    die(1, e.message);
  }
  try {
    body = readFileSync(bodyFile, "utf8");
  } catch {
    die(1, `body-file unreadable: ${bodyFile}`);
  }
  if (body.trim().length === 0) die(1, "body-file is empty — refusing to post an empty routing comment (W-4)");

  let res;
  try {
    res = await fetch(`${GH_API}/repos/${owner}/${repo}/issues/${prNumber}/comments`, {
      method: "POST",
      headers: {
        authorization: `Bearer ${token}`,
        accept: "application/vnd.github+json",
        "content-type": "application/json",
        "x-github-api-version": "2022-11-28",
        "user-agent": "kohuehara-workforce",
      },
      body: JSON.stringify({ body }),
    });
  } catch (e) {
    die(3, `network error: ${e instanceof Error ? e.message : String(e)}`);
  }
  if (res.status === 201) {
    const json = await res.json().catch(() => ({}));
    console.log(`pr-autopilot-post: posted to ${owner}/${repo}#${prNumber} (comment ${json.id ?? "?"})`);
    // Stamp escalation labels (best-effort: a label problem must not fail a
    // comment that already landed). Auto-create any label the repo lacks.
    // resolveLabels guarantees ESCALATION_LABEL whenever this comment hands the
    // PR to a human (--needs-human flag or the body marker).
    const labels = resolveLabels(labelArgs(), {
      needsHuman: flag("needs-human"),
      reviewed: flag("reviewed"),
      body,
    });
    if (labels.length > 0) {
      for (const name of labels) {
        const meta = LABEL_META[name] ?? FALLBACK_LABEL_META;
        const cr = await gh(token, "POST", `/repos/${owner}/${repo}/labels`, {
          name, color: meta.color, description: meta.description,
        }).catch(() => ({ status: 0 }));
        if (cr.status !== 201 && cr.status !== 422) {
          console.error(`pr-autopilot-post: WARN ensure label "${name}" → HTTP ${cr.status}`);
        }
      }
      const lr = await gh(token, "POST", `/repos/${owner}/${repo}/issues/${prNumber}/labels`, { labels }).catch(() => ({ status: 0 }));
      if (lr.status === 200) console.log(`pr-autopilot-post: labelled #${prNumber} [${labels.join(", ")}]`);
      else console.error(`pr-autopilot-post: WARN could not label #${prNumber} → HTTP ${lr.status}`);
    }
    process.exit(0);
  }
  const text = await res.text().catch(() => "");
  die(res.status < 500 ? 2 : 3, `POST comment → ${res.status}: ${text.slice(0, 300)}`);
}

function die(code, msg) {
  console.error(`pr-autopilot-post: ${msg}`);
  process.exit(code);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  main().catch((e) => die(3, e instanceof Error ? e.message : String(e)));
}

#!/usr/bin/env node
// Deterministic pr-autopilot SCAN script — GET-only discovery for the CCR
// cron-poll routing leg (ADR-0005). The CCR session runs this first to
// learn WHICH open PRs in the bound project's repo still need a cycle-1
// routing comment; it then applies the persona's nomination_rules (its
// judgment) and posts each routing comment via pr-autopilot-post.mjs.
//
// This script performs NO writes — it only issues GitHub GETs:
//   - list open PRs in the project repo
//   - read each PR's issue comments (to skip already-routed PRs)
//   - read each candidate PR's unified diff
// The (project × agent × skill) binding supplies project_id; the
// project linkage supplies the github.token (injected as GITHUB_TOKEN).
// The repo (owner/repo) is read from the in-repo project.json — the CCR
// session runs inside the workforce checkout.
//
// Discovery includes BOTH draft and non-draft PRs, and BOTH human- and
// bot-authored (Dependabot) PRs — every open PR in the window is routable
// (2026-06-17 Autopilot widening, adr-0010). The only discovery filters are
// the recency window and "already routed this cycle".
//
// Usage:
//   GITHUB_TOKEN=<credentials['github.token'].token> \
//     node workforce/skills/pr-autopilot/pr-autopilot-scan.mjs \
//       --project asp-cloud --persona nadia \
//       [--max 5] [--since-days 7] [--out /tmp/pr-autopilot-candidates.json]
//
// Output: writes a JSON array of candidate PRs to --out and prints a
// one-line summary to stdout. Exit 0 even when zero candidates (a valid
// "nothing to route this tick" outcome — the session then does nothing).
//
// Exit codes:
//   0  — scan completed (candidates written; may be an empty array)
//   1  — bad args / project.json missing or has no github.{owner,repo}
//   2  — GitHub auth/4xx (token missing or lacks repo read)
//   3  — network / unexpected error

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";

const GH_API = "https://api.github.com";
const MAX_DIFF_CHARS = 48_000; // ~12K tokens; protects the CCR context budget
const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..", ".."); // workforce/skills/pr-autopilot → repo root

function arg(name, fallback) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : fallback;
}

/** Resolve the project's GitHub surface from the in-repo project.json. */
export function projectRepo(repoRoot, projectId) {
  const path = join(repoRoot, "workforce", "projects", projectId, "project.json");
  let json;
  try {
    json = JSON.parse(readFileSync(path, "utf8"));
  } catch {
    throw new Error(`pr-autopilot-scan: project.json not found for "${projectId}" at ${path}`);
  }
  if (!json.github || !json.github.owner || !json.github.repo) {
    throw new Error(
      `pr-autopilot-scan: project "${projectId}" declares no github.{owner,repo} — pr-autopilot needs an external project repo`,
    );
  }
  return { owner: json.github.owner, repo: json.github.repo };
}

/** A PR has already been routed (this cycle leg) if a comment from this
 *  persona opens with the router-comment marker. Mirrors the marker that
 *  pr-autopilot-post writes via the SKILL.md comment template. */
export function alreadyRouted(comments, personaSlug) {
  const personaName = personaSlug.charAt(0).toUpperCase() + personaSlug.slice(1);
  const marker = new RegExp(`^\\*\\*${personaName} — cycle \\d+ of `, "m");
  return comments.some((c) => marker.test(c.body ?? ""));
}

/** Recency gate: only route PRs updated within the window (avoids
 *  mass-commenting a stale backlog on first cron tick). */
export function withinWindow(updatedAt, sinceDays, now = Date.now()) {
  const t = Date.parse(updatedAt);
  if (Number.isNaN(t)) return false;
  return now - t <= sinceDays * 24 * 60 * 60 * 1000;
}

async function ghGet(token, path, accept) {
  const res = await fetch(`${GH_API}${path}`, {
    headers: {
      authorization: `Bearer ${token}`,
      accept: accept ?? "application/vnd.github+json",
      "x-github-api-version": "2022-11-28",
      "user-agent": "kohuehara-workforce",
    },
  });
  if (!res.ok) {
    const body = await res.text();
    const err = new Error(`GitHub GET ${path} → ${res.status}: ${body.slice(0, 300)}`);
    err.httpStatus = res.status;
    throw err;
  }
  return accept?.includes("vnd.github.v3.diff") ? res.text() : res.json();
}

async function main() {
  const projectId = arg("project");
  const persona = arg("persona");
  const max = Number(arg("max", "5"));
  const sinceDays = Number(arg("since-days", "7"));
  const out = arg("out", "/tmp/pr-autopilot-candidates.json");
  const token = process.env.GITHUB_TOKEN;

  if (!projectId) die(1, "--project <id> is required");
  if (!persona) die(1, "--persona <agent-slug> is required (the routing persona)");
  if (!token) die(2, "GITHUB_TOKEN env is required (from credentials['github.token'].token)");
  if (!Number.isInteger(max) || max < 1) die(1, `--max must be a positive integer (got ${max})`);

  let owner, repo;
  try {
    ({ owner, repo } = projectRepo(REPO_ROOT, projectId));
  } catch (e) {
    die(1, e.message);
  }

  // List ALL open PRs (draft + non-draft, human + bot), most-recently-updated
  // first. Draft/bot are no longer discovery filters (adr-0010).
  let prs;
  try {
    prs = await ghGet(token, `/repos/${owner}/${repo}/pulls?state=open&sort=updated&direction=desc&per_page=50`);
  } catch (e) {
    die(e.httpStatus && e.httpStatus < 500 ? 2 : 3, e.message);
  }

  const candidates = [];
  for (const pr of prs) {
    if (candidates.length >= max) break;
    // Draft and bot-authored PRs are IN scope (adr-0010): drafts get an early
    // review pass, and Dependabot PRs route through the same review→consensus
    // →merge path as human PRs (the dependabot-triage no-review lane retires).
    if (!withinWindow(pr.updated_at, sinceDays)) continue;
    let comments;
    try {
      comments = await ghGet(token, `/repos/${owner}/${repo}/issues/${pr.number}/comments?per_page=100`);
    } catch (e) {
      die(e.httpStatus && e.httpStatus < 500 ? 2 : 3, e.message);
    }
    if (alreadyRouted(comments, persona)) continue;

    let diff;
    try {
      diff = await ghGet(token, `/repos/${owner}/${repo}/pulls/${pr.number}`, "application/vnd.github.v3.diff");
    } catch (e) {
      die(e.httpStatus && e.httpStatus < 500 ? 2 : 3, e.message);
    }
    if (diff.length > MAX_DIFF_CHARS) {
      diff = diff.slice(0, MAX_DIFF_CHARS) + `\n\n... [diff truncated at ${MAX_DIFF_CHARS} chars] ...\n`;
    }
    candidates.push({
      number: pr.number,
      title: pr.title,
      body: pr.body ?? "",
      author: pr.user?.login ?? "(unknown)",
      draft: pr.draft === true,
      is_bot: pr.user?.type === "Bot" || /\[bot\]$/.test(pr.user?.login ?? ""),
      base: pr.base?.ref ?? "",
      head: pr.head?.ref ?? "",
      html_url: pr.html_url,
      updated_at: pr.updated_at,
      comments: comments
        .slice(0, 30)
        .map((c) => ({ author: c.user?.login ?? "(unknown)", body: (c.body ?? "").slice(0, 240).replace(/\n+/g, " ") })),
      diff,
    });
  }

  writeFileSync(out, JSON.stringify({ project_id: projectId, owner, repo, persona, candidates }, null, 2));
  console.log(
    `pr-autopilot-scan: ${owner}/${repo} — ${candidates.length} candidate PR(s) need cycle-1 routing (scanned ${prs.length} open, max ${max}, window ${sinceDays}d) → ${out}`,
  );
  process.exit(0);
}

function die(code, msg) {
  console.error(`pr-autopilot-scan: ${msg}`);
  process.exit(code);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  main().catch((e) => die(3, e instanceof Error ? e.message : String(e)));
}

// @ts-nocheck — the engine under test (pr-merge.mjs) is a dependency-free ESM
// script, not TS; vitest/esbuild imports it fine at runtime, and this suite is
// not shipped code. Discovered by workforce/lambdas/vitest.config.mjs
// (`include: ["../skills/**/*-tests.ts"]`), so `cd workforce/lambdas && npm test`
// (the CI step) runs it. Closes Sana's C1: the merge-gating predicate's
// regression net lives in the repo, not a session transcript (adr-0010).
import { describe, it, expect } from "vitest";
import {
  globToRegExp,
  resolveL0L1Paths,
  reviewerSignedOff,
  reviewerGreenMarker,
  countRouterCycles,
  W4_CYCLE_CAP,
  verifyMergeable,
  applyDecisions,
  markReadyForReview,
  ESCALATION_LABEL,
} from "./pr-merge.mjs";

/** Route a `${method} ${path}` string to a canned {status,json} response. */
function mockGh(routes) {
  const calls = [];
  const gh = async (method, path, body) => {
    calls.push({ method, path, body });
    for (const [re, resp] of routes) {
      if (re.test(`${method} ${path}`)) return typeof resp === "function" ? resp() : resp;
    }
    return { status: 404, json: {} };
  };
  // GraphQL leg (adr-0014). Routes match against `GRAPHQL <query>`; default is a
  // successful markReadyForReview so non-draft merge tests are unaffected.
  gh.graphql = async (query, variables) => {
    calls.push({ method: "GRAPHQL", path: query, body: variables });
    for (const [re, resp] of routes) {
      if (re.test(`GRAPHQL ${query}`)) return typeof resp === "function" ? resp() : resp;
    }
    return { status: 200, json: { data: { markPullRequestReadyForReview: { pullRequest: { isDraft: false } } } } };
  };
  gh.calls = calls;
  return gh;
}

const govDoc = (block) => ({
  status: 200,
  json: { encoding: "base64", content: Buffer.from(`# gov\n${block}\n`).toString("base64") },
});
const L0_BLOCK =
  "<!-- autopilot:l0l1-paths -->\n- docs/governance.md\n- docs/adr/**\n<!-- /autopilot:l0l1-paths -->";
const GREEN_CHECK = [{ name: "ci", status: "completed", conclusion: "success" }];
// A non-blocking lens review carries the exact structured green marker.
const DARIO_REVIEW = [{ state: "COMMENTED", body: `looks good\n\n${reviewerGreenMarker("dario")}` }];

/** Standard happy-path route table, parameterised by the variable bits. */
const routes = (files, checks, reviews, comments = []) => [
  [/GET \/repos\/o\/r\/pulls\/1$/, { status: 200, json: { state: "open", mergeable: true, mergeable_state: "clean", head: { sha: "abc" }, base: { ref: "main" } } }],
  [/GET .*contents/, govDoc(L0_BLOCK)],
  [/GET \/repos\/o\/r\/pulls\/1\/files/, { status: 200, json: files }],
  [/GET \/repos\/o\/r\/commits\/abc\/check-runs/, { status: 200, json: { check_runs: checks } }],
  [/GET \/repos\/o\/r\/pulls\/1\/reviews/, { status: 200, json: reviews }],
  [/GET \/repos\/o\/r\/issues\/1\/comments/, { status: 200, json: comments }],
];

describe("globToRegExp", () => {
  it("matches an exact path", () => expect(globToRegExp("docs/governance.md").test("docs/governance.md")).toBe(true));
  it("** spans slashes", () => expect(globToRegExp("docs/adr/**").test("docs/adr/adr-1.md")).toBe(true));
  it("** does not false-match a sibling", () => expect(globToRegExp("docs/adr/**").test("docs/adrx.md")).toBe(false));
  it("* stays within a segment", () => {
    expect(globToRegExp("src/*.ts").test("src/a.ts")).toBe(true);
    expect(globToRegExp("src/*.ts").test("src/sub/a.ts")).toBe(false);
  });
});

describe("reviewerSignedOff (exact structured marker, not byline)", () => {
  it("matches the exact green marker", () => expect(reviewerSignedOff("dario", [`ok\n${reviewerGreenMarker("dario")}`])).toBe(true));
  it("is case-insensitive on the slug token", () => expect(reviewerSignedOff("Ren", ["<!-- AUTOPILOT:REVIEW:REN:GREEN -->"])).toBe(true));
  it("does NOT count a byline/prose mention as a green vote (no false-open)", () => expect(reviewerSignedOff("dario", ["x\n— Dario (CCR) looks good"])).toBe(false));
  it("does NOT count a :red marker", () => expect(reviewerSignedOff("dario", ["<!-- autopilot:review:dario:red -->"])).toBe(false));
  it("is false when the persona never signed", () => expect(reviewerSignedOff("aoi", ["nothing here"])).toBe(false));
});

describe("resolveL0L1Paths (source of truth = target repo governance)", () => {
  it("parses the declared block", async () => {
    const r = await resolveL0L1Paths(mockGh([[/GET .*contents/, govDoc(L0_BLOCK)]]), "o/r", "main");
    expect(r.ok).toBe(true);
    expect(r.patterns).toHaveLength(2);
  });
  it("fails closed when the governance doc is unreadable", async () => {
    const r = await resolveL0L1Paths(mockGh([[/GET .*contents/, { status: 404, json: {} }]]), "o/r", "main");
    expect(r.ok).toBe(false);
  });
  it("fails closed when the markers are absent", async () => {
    const r = await resolveL0L1Paths(mockGh([[/GET .*contents/, govDoc("no markers here")]]), "o/r", "main");
    expect(r.ok).toBe(false);
  });
});

describe("verifyMergeable (fail-closed predicate)", () => {
  it("passes on a non-L0/L1, green, consensus PR", async () => {
    const v = await verifyMergeable(mockGh(routes([{ filename: "src/app.ts" }], GREEN_CHECK, DARIO_REVIEW)), "o/r", 1, { reviewers: ["dario"] });
    expect(v.ok).toBe(true);
  });
  it("refuses a PR touching an L0/L1 path", async () => {
    const v = await verifyMergeable(mockGh(routes([{ filename: "docs/governance.md" }], GREEN_CHECK, DARIO_REVIEW)), "o/r", 1, { reviewers: ["dario"] });
    expect(v.ok).toBe(false);
    expect(v.why).toMatch(/L0\/L1/);
  });
  it("refuses when a reviewer requested changes", async () => {
    const v = await verifyMergeable(mockGh(routes([{ filename: "src/app.ts" }], GREEN_CHECK, [{ state: "CHANGES_REQUESTED", body: "x" }])), "o/r", 1, { reviewers: ["dario"] });
    expect(v.ok).toBe(false);
    expect(v.why).toMatch(/CHANGES_REQUESTED/);
  });
  it("refuses when a required check is not green", async () => {
    const v = await verifyMergeable(mockGh(routes([{ filename: "src/app.ts" }], [{ name: "ci", status: "completed", conclusion: "failure" }], DARIO_REVIEW)), "o/r", 1, { reviewers: ["dario"] });
    expect(v.ok).toBe(false);
  });
  it("refuses a no-review merge (empty reviewers[])", async () => {
    const v = await verifyMergeable(mockGh(routes([{ filename: "src/app.ts" }], GREEN_CHECK, [])), "o/r", 1, { reviewers: [] });
    expect(v.ok).toBe(false);
    expect(v.why).toMatch(/reviewers/);
  });
  it("refuses when a nominated reviewer's lens review is missing", async () => {
    const v = await verifyMergeable(mockGh(routes([{ filename: "src/app.ts" }], GREEN_CHECK, DARIO_REVIEW)), "o/r", 1, { reviewers: ["dario", "ren"] });
    expect(v.ok).toBe(false);
    expect(v.why).toMatch(/ren/);
  });
  // adr-0011: the workforce's own repo is a normal delegated target — no own-repo
  // veto. The single boundary is the L0/L1 path set, so a reviewed non-L0/L1 PR
  // passes (next test) while a governance PR still escalates (the one after).
  const ownRepoRoutes = (files) => [
    [/GET \/repos\/refluster\/ai-native-article\/pulls\/1$/, { status: 200, json: { state: "open", mergeable: true, mergeable_state: "clean", head: { sha: "abc" }, base: { ref: "main" } } }],
    [/GET .*contents/, govDoc(L0_BLOCK)],
    [/GET \/repos\/refluster\/ai-native-article\/pulls\/1\/files/, { status: 200, json: files }],
    [/GET \/repos\/refluster\/ai-native-article\/commits\/abc\/check-runs/, { status: 200, json: { check_runs: GREEN_CHECK } }],
    [/GET \/repos\/refluster\/ai-native-article\/pulls\/1\/reviews/, { status: 200, json: DARIO_REVIEW }],
    [/GET \/repos\/refluster\/ai-native-article\/issues\/1\/comments/, { status: 200, json: [] }],
  ];
  it("passes an own-repo, non-L0/L1, green, consensus PR (adr-0011: no own-repo veto)", async () => {
    const v = await verifyMergeable(mockGh(ownRepoRoutes([{ filename: "workforce/app/src/pages/Messaging.tsx" }])), "refluster/ai-native-article", 1, { reviewers: ["dario"] });
    expect(v.ok).toBe(true);
  });
  it("still refuses an own-repo PR that touches L0/L1 — the boundary holds", async () => {
    const v = await verifyMergeable(mockGh(ownRepoRoutes([{ filename: "docs/governance.md" }])), "refluster/ai-native-article", 1, { reviewers: ["dario"] });
    expect(v.ok).toBe(false);
    expect(v.why).toMatch(/L0\/L1/);
  });
  it("refuses when the maintainer set the autopilot:off label", async () => {
    const v = await verifyMergeable(
      mockGh([[/GET \/repos\/o\/r\/pulls\/1$/, { status: 200, json: { state: "open", mergeable: true, mergeable_state: "clean", labels: [{ name: "autopilot:off" }], head: { sha: "abc" }, base: { ref: "main" } } }]]),
      "o/r", 1, { reviewers: ["dario"] },
    );
    expect(v.ok).toBe(false);
    expect(v.why).toMatch(/autopilot:off/);
  });
  it("refuses when the PR is not mergeable/clean", async () => {
    const v = await verifyMergeable(
      mockGh([[/GET \/repos\/o\/r\/pulls\/1$/, { status: 200, json: { state: "open", mergeable: false, mergeable_state: "dirty", head: { sha: "abc" }, base: { ref: "main" } } }]]),
      "o/r", 1, { reviewers: ["dario"] },
    );
    expect(v.ok).toBe(false);
  });
});

describe("countRouterCycles (FU-004)", () => {
  it("returns 0 for empty input", () => expect(countRouterCycles([])).toBe(0));
  it("returns 0 when no routing comment is present", () =>
    expect(countRouterCycles(["no routing here", "just a review comment"])).toBe(0));
  it("detects cycle 1 from a canonical routing comment", () =>
    expect(countRouterCycles(["**Nadia — cycle 1 of ≤ 7.**\n\nPR summary…"])).toBe(1));
  it("detects the highest cycle across multiple routing comments", () =>
    expect(countRouterCycles([
      "**Nadia — cycle 1 of ≤ 7.**",
      "other comment",
      "**Nadia — cycle 3 of ≤ 7.**",
    ])).toBe(3));
  it("matches when persona name contains a space", () =>
    expect(countRouterCycles(["**Some Name — cycle 2 of ≤ 7.**"])).toBe(2));
  it("W4_CYCLE_CAP is 7", () => expect(W4_CYCLE_CAP).toBe(7));
});

describe("verifyMergeable — W-4 cycle cap (FU-004)", () => {
  it("allows merge when cycle equals W4_CYCLE_CAP (exactly 7)", async () => {
    const gh = mockGh(routes(
      [{ filename: "src/app.ts" }],
      GREEN_CHECK,
      DARIO_REVIEW,
      [{ body: "**Nadia — cycle 7 of ≤ 7.**\n\nsummary" }],
    ));
    const v = await verifyMergeable(gh, "o/r", 1, { reviewers: ["dario"] });
    expect(v.ok).toBe(true);
  });
  it("refuses merge when cycle exceeds W4_CYCLE_CAP (cycle = 8)", async () => {
    const gh = mockGh(routes(
      [{ filename: "src/app.ts" }],
      GREEN_CHECK,
      DARIO_REVIEW,
      [{ body: "**Nadia — cycle 8 of ≤ 7.**\n\nsummary" }],
    ));
    const v = await verifyMergeable(gh, "o/r", 1, { reviewers: ["dario"] });
    expect(v.ok).toBe(false);
    expect(v.why).toMatch(/W-4/);
    expect(v.why).toMatch(/cycle 8/);
  });
});

describe("applyDecisions (merge path — approve is advisory, not a gate)", () => {
  const MERGE_DECISION = {
    pr: 1, action: "merge", comment: "consensus-green, merging", reviewers: ["dario"],
    squash_subject: "feat: thing (#1)", squash_body: "Unanimous sign-off (dario).",
  };
  // verifyMergeable's GET routes (green, non-L0/L1, consensus) + the write legs.
  const mergeRoutes = (approveResp) => [
    ...routes([{ filename: "workforce/lambdas/shared/x.ts" }], GREEN_CHECK, DARIO_REVIEW),
    [/POST \/repos\/o\/r\/issues\/1\/comments/, { status: 201, json: {} }],
    [/POST \/repos\/o\/r\/pulls\/1\/reviews/, approveResp],
    [/PUT \/repos\/o\/r\/pulls\/1\/merge/, { status: 200, json: { merged: true } }],
  ];
  const OWN_PR_422 = { status: 422, json: { message: "Unprocessable Entity", errors: ["Review Can not approve your own pull request"] } };

  it("merges a green own-identity PR even though self-approve 422s (the #361 stall fix)", async () => {
    const gh = mockGh(mergeRoutes(OWN_PR_422));
    const res = await applyDecisions(gh, "o/r", [MERGE_DECISION]);
    expect(res.merged).toBe(1);
    expect(res.refused).toBe(0);
    // The merge PUT — the real gate — must have been reached despite the 422.
    expect(gh.calls.some((c) => c.method === "PUT" && /\/merge$/.test(c.path))).toBe(true);
  });

  it("still merges on a normal approve (200) — non-self-authored path unbroken", async () => {
    const res = await applyDecisions(mockGh(mergeRoutes({ status: 200, json: {} })), "o/r", [MERGE_DECISION]);
    expect(res.merged).toBe(1);
    expect(res.refused).toBe(0);
  });

  it("does NOT merge when the predicate fails (verifyMergeable refuses) even if approve would 422", async () => {
    // L0/L1-touching PR → verifyMergeable refuses before any write leg runs.
    const gh = mockGh([
      ...routes([{ filename: "docs/governance.md" }], GREEN_CHECK, DARIO_REVIEW),
