    ]);
    const res = await applyDecisions(gh, "o/r", [MERGE_DECISION]);
    expect(res.merged).toBe(0);
    expect(res.refused).toBe(1);
    expect(gh.calls.some((c) => c.method === "PUT" && /\/merge$/.test(c.path))).toBe(false);
  });
});

